// One-time import: a real three-way merge with pinned, reviewed resolutions.
// Only the explicitly authorized migration branch can be pushed.
import { execFileSync, spawnSync } from 'node:child_process';
import { writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { dirname } from 'node:path';
import { gunzipSync } from 'node:zlib';
const branch = 'agent/movix-upstream-sync-v1';
const source = '030e68eef05a20845a1e1d97e83913c5b89986c7';
const upstream = '0e7cd866fa5bbb248c2e24c1d5d69e7f06e38ce5';
const ancestor = 'ff56b3c57511c84cedc89956ba05dedba7630f1d';
const targetTree = '88bfb7e39620a8bebab750c0cff99c05084e85bf';
function git(...args) { return execFileSync('git', args, {encoding:'utf8'}).trim(); }
if (process.env.GITHUB_REPOSITORY !== '2Spartiate/MovixOpenSource' || process.env.GITHUB_REF !== `refs/heads/${branch}`) throw new Error('Unauthorized repository or branch');
if (git('rev-parse','HEAD^') !== source) throw new Error('Bootstrap must directly follow the pinned custom branch');
git('config','user.name','github-actions[bot]');
git('config','user.email','41898282+github-actions[bot]@users.noreply.github.com');
git('remote','add','movix-upstream','https://github.com/movixstream/MovixOpenSource.git');
git('fetch','--filter=blob:none','movix-upstream',upstream);
if (git('merge-base','HEAD',upstream) !== ancestor) throw new Error('Unexpected merge base');
const merge = spawnSync('git',['merge','--no-commit','--no-ff',upstream],{stdio:'inherit'});
if (![0,1].includes(merge.status)) throw new Error('Git merge failed');
const overrides = JSON.parse(gunzipSync(Buffer.from('','base64')).toString('utf8'));
for (const {path,content} of overrides) {
  if (!/^(?:app|src|docs)\//.test(path) || path.includes('..')) throw new Error('Unexpected resolution path');
  if (content === null) { git('rm','-f','--ignore-unmatch','--',path); rmSync(path,{force:true}); }
  else { mkdirSync(dirname(path),{recursive:true}); writeFileSync(path,content); git('add','-f','--',path); }
}
for (const path of ['.github/workflows/movix-upstream-import-v1.yml','.github/movix-upstream-import-v1.mjs']) git('rm','-f','--',path);
if (git('diff','--name-only','--diff-filter=U')) throw new Error('Unresolved conflicts');
if (git('write-tree') !== targetTree) throw new Error('Merged tree differs from the locally reviewed and validated tree');
git('diff','--cached','--check');
git('commit','-m','merge(upstream): integrate Movix 2.6.5 and preserve Google TV V22 and parental controls');
if (git('rev-parse','HEAD^2') !== upstream) throw new Error('Missing real upstream parent');
git('push','origin',`HEAD:refs/heads/${branch}`);
console.log('Validated three-way merge pushed:',git('rev-parse','HEAD'));
